<template>
  <div
    class="modal fade mymodal"
    id="note-modal"
    data-bs-backdrop="false"
    data-bs-keyboard="false"
    tabindex="-1"
    aria-hidden="true"
    ref="modalEl"
  >
    <div class="modal-dialog modal-lg modal-dialog-centered">
      <div class="modal-content" style="border-radius:20px;max-height:80vh;display:flex;flex-direction:column;">

        <!-- Header -->
        <div class="modal-header" style="padding:14px 18px;border-bottom:0.5px solid #dee2e6;">
          <span style="font-size:15px;font-weight:500;">
            Notes for {{ title }} No. {{ activeSourceId }}
          </span>
          <button
            v-if="canRequestCancellation"
            type="button"
            class="btn btn-warning ms-auto"
            @click="cancellationRequest = !cancellationRequest"
            :disabled="submitting"
          >
            {{ cancellationRequest ? 'Cancel' : 'Request Cancellation' }}
          </button>
          <button type="button" class="btn-close ms-auto" data-bs-dismiss="modal"></button>
        </div>

        <!-- Body / Feed -->
        <div class="modal-body" style="overflow-y:auto;flex:1;padding:16px 18px;">

          <div v-if="logsLoading" class="text-center py-4">
            <span v-html="waitIndicator()"></span>
          </div>

          <div v-else-if="logs.length === 0" class="text-center text-muted py-5">
            <svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" fill="currentColor"
                 class="bi bi-chat-square-dots mb-2 d-block mx-auto" viewBox="0 0 16 16">
              <path d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1h-2.5a2 2 0 0 0-1.6.8L8 14.333
                       6.1 11.8a2 2 0 0 0-1.6-.8H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1z"/>
            </svg>
            No notes yet for {{ title }} No. {{ activeSourceId }}
          </div>

          <!-- Comment thread -->
          <div v-else class="d-flex flex-column gap-4">
            <div v-for="log in logs" :key="log.id">

              <!-- Level 1: Parent comment -->
              <div class="d-flex gap-2 align-items-start">
                <div class="avatar-circle flex-shrink-0"
                     :style="{ background: avatarBg(log.reporter?.name), color: avatarColor(log.reporter?.name) }">
                  {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
                </div>
                <div class="flex-grow-1">
                  <div class="d-flex align-items-center gap-2 mb-1 flex-wrap">
                    <strong style="font-size:15px;">{{ log.reporter?.name }}</strong>
                    <small class="text-dark" style="font-size:12px;text-transform:lowercase;">{{ log.type }}</small>
                    <small class="text-dark">{{ formatDate(log.created_at) }}</small>
                  </div>

                  <!-- View mode -->
                  <div v-if="editingLog !== log.id" class="d-flex align-items-start gap-3">
                    <p style="font-size:16px;line-height:1.5;margin:0 0 6px;color:#212529;">{{ log.description }}</p>
                    <svg v-if="log.reporter?.id === userId"
                         xmlns="http://www.w3.org/2000/svg" width="13" height="13" fill="currentColor"
                         class="bi bi-pen-fill" style="cursor:pointer;flex-shrink:0;margin-top:4px;"
                         viewBox="0 0 16 16" @click="startEdit(log)">
                      <path d="m13.498.795.149-.149a1.207 1.207 0 1 1 1.707 1.708l-.149.148a1.5 1.5 0 0 1-.059 2.059L4.854 14.854a.5.5 0 0 1-.233.131l-4 1a.5.5 0 0 1-.606-.606l1-4a.5.5 0 0 1 .131-.232l9.642-9.642a.5.5 0 0 0-.642.056L6.854 4.854a.5.5 0 1 1-.708-.708L9.44.854A1.5 1.5 0 0 1 11.5.796a1.5 1.5 0 0 1 1.998-.001"/>
                    </svg>
                    <i v-if="isProgrammer" class="bi bi-trash3 text-danger" style="cursor:pointer;"
                       @click="deleteRemark(log.id)"></i>
                  </div>

                  <!-- Edit mode -->
                  <div v-else class="d-flex gap-2 align-items-center mb-2">
                    <input type="text" class="form-control form-control-sm"
                           style="border-radius:20px;font-size:15px;"
                           v-model="editText"
                           @keyup.enter="updateLog(log)"
                           @keyup.escape="cancelEdit()" />
                    <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:12px;"
                            @click="updateLog(log)" :disabled="submitting">Save</button>
                    <button class="btn btn-sm btn-link text-muted p-0" @click="cancelEdit()">Cancel</button>
                  </div>

                  <!-- Reply toggle + count -->
                  <div class="d-flex align-items-center gap-3">
                    <button class="btn btn-link btn-sm p-0 text-muted" style="font-size:15px;"
                            @click="toggleReply(`log-${log.id}`)">
                      <svg width="12" height="12" fill="currentColor" class="me-1" viewBox="0 0 16 16">
                        <path d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1H4.414A2 2 0 0 0 3 11.586l-2 2V2a1 1 0 0 1 1-1z"/>
                      </svg>
                      Reply
                    </button>
                    <small v-if="log.replies?.length" class="text-muted">
                      {{ log.replies.length }} {{ log.replies.length === 1 ? 'reply' : 'replies' }}
                    </small>
                  </div>

                  <!-- Reply input: level 1 -->
                  <div v-if="replyingTo === `log-${log.id}`" class="d-flex gap-2 align-items-center mt-2">
                    <input type="text" class="form-control form-control-sm"
                           style="border-radius:20px;font-size:15px;"
                           :placeholder="`Reply to ${log.reporter?.name}...`"
                           v-model="newMessage" @keyup.enter="submitLog(log.id)" />
                    <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:12px;"
                            @click="submitLog(log.id)">Send</button>
                    <button class="btn btn-sm btn-link text-danger p-0"
                            @click="replyingTo = null; newMessage = ''">Cancel</button>
                  </div>

                  <!-- Level 2: Replies -->
                  <div v-if="log.replies?.length" class="mt-3 d-flex flex-column gap-3">
                    <div v-for="reply in log.replies" :key="reply.id" class="d-flex gap-2 align-items-start">
                      <div class="avatar-circle avatar-sm flex-shrink-0"
                           :style="{ background: avatarBg(reply.reporter?.name), color: avatarColor(reply.reporter?.name) }">
                        {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
                      </div>
                      <div class="flex-grow-1">
                        <div class="d-flex align-items-center gap-2 mb-1 flex-wrap">
                          <strong style="font-size:15px;">{{ reply.reporter?.name }}</strong>
                          <small class="text-muted" style="font-size:13px;text-transform:lowercase;">{{ reply.type }}</small>
                          <small class="text-muted" style="font-size:13px;">{{ formatDate(reply.created_at) }}</small>
                        </div>

                        <div v-if="reply.type === 'MESSAGE'">
                          <!-- View mode -->
                          <div v-if="editingLog !== reply.id" class="d-flex align-items-start gap-3">
                            <p style="font-size:13px;line-height:1.5;margin:0 0 6px;color:#212529;">{{ reply.description }}</p>
                            <svg v-if="reply.reporter?.id === userId"
                                 xmlns="http://www.w3.org/2000/svg" width="13" height="13" fill="currentColor"
                                 class="bi bi-pen-fill" style="cursor:pointer;flex-shrink:0;margin-top:3px;"
                                 viewBox="0 0 16 16" @click="startEdit(reply)">
                              <path d="m13.498.795.149-.149a1.207 1.207 0 1 1 1.707 1.708l-.149.148a1.5 1.5 0 0 1-.059 2.059L4.854 14.854a.5.5 0 0 1-.233.131l-4 1a.5.5 0 0 1-.606-.606l1-4a.5.5 0 0 1 .131-.232l9.642-9.642a.5.5 0 0 0-.642.056L6.854 4.854a.5.5 0 1 1-.708-.708L9.44.854A1.5 1.5 0 0 1 11.5.796a1.5 1.5 0 0 1 1.998-.001"/>
                            </svg>
                          </div>
                          <!-- Edit mode -->
                          <div v-else class="d-flex gap-2 align-items-center mb-2">
                            <input type="text" class="form-control form-control-sm"
                                   style="border-radius:20px;font-size:13px;"
                                   v-model="editText"
                                   @keyup.enter="updateLog(reply)"
                                   @keyup.escape="cancelEdit()" />
                            <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:12px;"
                                    @click="updateLog(reply)" :disabled="submitting">Save</button>
                            <button class="btn btn-sm btn-link text-muted p-0" @click="cancelEdit()">Cancel</button>
                          </div>
                        </div>

                        <p v-else style="font-size:13px;font-style:italic;margin:0 0 6px;color:#212529;">
                          {{ reply.description }}
                          <i v-if="isProgrammer" class="bi bi-trash3 text-danger me-5" style="cursor:pointer;"
                             @click="deleteRemark(reply.id)"></i>
                        </p>

                        <!-- Reply toggle: level 2 -->
                        <div class="d-flex align-items-center gap-3">
                          <button class="btn btn-link btn-sm p-0 text-muted" style="font-size:12px;"
                                  @click="toggleReply(`reply-${reply.id}`)">
                            <svg width="12" height="12" fill="currentColor" class="me-1" viewBox="0 0 16 16">
                              <path d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1H4.414A2 2 0 0 0 3 11.586l-2 2V2a1 1 0 0 1 1-1z"/>
                            </svg>
                            Reply
                          </button>
                          <small v-if="reply.replies?.length" class="text-muted">
                            {{ reply.replies.length }} {{ reply.replies.length === 1 ? 'reply' : 'replies' }}
                          </small>
                        </div>

                        <!-- Reply input: level 2 -->
                        <div v-if="replyingTo === `reply-${reply.id}`" class="d-flex gap-2 align-items-center mt-2">
                          <input type="text" class="form-control form-control-sm"
                                 style="border-radius:20px;font-size:13px;"
                                 :placeholder="`Reply to ${reply.reporter?.name}...`"
                                 v-model="newMessage"
                                 @keyup.enter="submitLog(reply.id)" />
                          <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:12px;"
                                  @click="submitLog(reply.id)">Send</button>
                          <button class="btn btn-sm btn-link text-muted p-0"
                                  @click="replyingTo = null; newMessage = ''">Cancel</button>
                        </div>

                        <!-- Level 3: Nested replies -->
                        <div v-if="reply.replies?.length" class="mt-2 d-flex flex-column gap-2">
                          <div v-for="nested in reply.replies" :key="nested.id" class="d-flex gap-2 align-items-start">
                            <div class="avatar-circle avatar-xs flex-shrink-0"
                                 :style="{ background: avatarBg(nested.reporter?.name), color: avatarColor(nested.reporter?.name) }">
                              {{ nested.reporter?.name?.charAt(0)?.toUpperCase() }}
                            </div>
                            <div class="flex-grow-1">
                              <div class="d-flex align-items-center gap-2 mb-1 flex-wrap">
                                <strong style="font-size:14px;">{{ nested.reporter?.name }}</strong>
                                <small class="text-muted" style="font-size:12px;text-transform:lowercase;">{{ nested.type }}</small>
                                <small class="text-muted" style="font-size:12px;">{{ formatDate(nested.created_at) }}</small>
                              </div>

                              <div v-if="nested.type === 'MESSAGE'">
                                <!-- View mode -->
                                <div v-if="editingLog !== nested.id" class="d-flex align-items-start gap-3">
                                  <p style="font-size:13px;line-height:1.5;margin:0 0 6px;color:#212529;">{{ nested.description }}</p>
                                  <svg v-if="nested.reporter?.id === userId"
                                       xmlns="http://www.w3.org/2000/svg" width="13" height="13" fill="currentColor"
                                       class="bi bi-pen-fill" style="cursor:pointer;flex-shrink:0;margin-top:3px;"
                                       viewBox="0 0 16 16" @click="startEdit(nested)">
                                    <path d="m13.498.795.149-.149a1.207 1.207 0 1 1 1.707 1.708l-.149.148a1.5 1.5 0 0 1-.059 2.059L4.854 14.854a.5.5 0 0 1-.233.131l-4 1a.5.5 0 0 1-.606-.606l1-4a.5.5 0 0 1 .131-.232l9.642-9.642a.5.5 0 0 0-.642.056L6.854 4.854a.5.5 0 1 1-.708-.708L9.44.854A1.5 1.5 0 0 1 11.5.796a1.5 1.5 0 0 1 1.998-.001"/>
                                  </svg>
                                </div>
                                <!-- Edit mode -->
                                <div v-else class="d-flex gap-2 align-items-center mb-2">
                                  <input type="text" class="form-control form-control-sm"
                                         style="border-radius:20px;font-size:13px;"
                                         v-model="editText"
                                         @keyup.enter="updateLog(nested)"
                                         @keyup.escape="cancelEdit()" />
                                  <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:12px;"
                                          @click="updateLog(nested)" :disabled="submitting">Save</button>
                                  <button class="btn btn-sm btn-link text-muted p-0" @click="cancelEdit()">Cancel</button>
                                </div>
                              </div>

                              <p v-else style="font-size:13px;font-style:italic;margin:0 0 4px;color:#212529;">
                                {{ nested.description }}
                              </p>

                              <!-- Reply toggle: level 3 -->
                              <button class="btn btn-link btn-sm p-0 text-muted" style="font-size:11px;"
                                      @click="toggleReply(`nested-${nested.id}`)">
                                <svg width="11" height="11" fill="currentColor" class="me-1" viewBox="0 0 16 16">
                                  <path d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1H4.414A2 2 0 0 0 3 11.586l-2 2V2a1 1 0 0 1 1-1z"/>
                                </svg>
                                Reply
                              </button>

                              <!-- Reply input: level 3 -->
                              <div v-if="replyingTo === `nested-${nested.id}`" class="d-flex gap-2 align-items-center mt-2">
                                <input type="text" class="form-control form-control-sm"
                                       style="border-radius:20px;font-size:15px;"
                                       :placeholder="`Reply to ${nested.reporter?.name}...`"
                                       v-model="newMessage"
                                       @keyup.enter="submitLog(nested.id)" />
                                <button class="btn btn-sm btn-primary px-3" style="border-radius:20px;font-size:11px;"
                                        @click="submitLog(nested.id)">Send</button>
                                <button class="btn btn-sm btn-link text-muted p-0"
                                        @click="replyingTo = null; newMessage = ''">Cancel</button>
                              </div>

                            </div>
                          </div>
                        </div>
                        <!-- end level 3 -->

                      </div>
                    </div>
                  </div>
                  <!-- end level 2 -->

                </div>
              </div>

            </div>
          </div>
        </div>

        <!-- Footer: new note input -->
        <div class="modal-footer" style="padding:12px 16px;border-top:0.5px solid #dee2e6;">
          <div class="d-flex gap-2 align-items-center w-100">
            <div class="avatar-circle avatar-sm flex-shrink-0"
                 :style="{ background: avatarBg(currentUserName), color: avatarColor(currentUserName) }">
              {{ currentUserName?.charAt(0)?.toUpperCase() }}
            </div>
            <input type="text" class="form-control" style="border-radius:24px;font-size:14px;"
                   placeholder="Add a note..." v-model="newMessage"
                   @keyup.enter="cancellationRequest ? emit('request-cancellation', newMessage) : submitLog(null)" />
            <button
              v-if="cancellationRequest"
              class="btn btn-warning d-flex align-items-center justify-content-center flex-shrink-0"
              style="width:38px;height:38px;border-radius:50%;padding:0;"
              @click="emit('request-cancellation', newMessage)"
              :disabled="!newMessage.trim() || submitting"
            >
              <svg width="15" height="15" fill="none" stroke="white" stroke-width="2" viewBox="0 0 24 24">
                <line x1="22" y1="2" x2="11" y2="13"/>
                <polygon points="22 2 15 22 11 13 2 9 22 2"/>
              </svg>
            </button>
            <button
              v-else
              class="btn btn-primary d-flex align-items-center justify-content-center flex-shrink-0"
              style="width:38px;height:38px;border-radius:50%;padding:0;"
              @click="submitLog(null)"
              :disabled="!newMessage.trim() || submitting"
            >
              <svg width="15" height="15" fill="none" stroke="white" stroke-width="2" viewBox="0 0 24 24">
                <line x1="22" y1="2" x2="11" y2="13"/>
                <polygon points="22 2 15 22 11 13 2 9 22 2"/>
              </svg>
            </button>
          </div>
        </div>

      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, inject } from 'vue'
import { Modal } from 'bootstrap'
import axios from 'axios'


const props = defineProps({

  source: { type: String, required: true },

  module: { type: String, required: true },

  title: { type: String, default: 'Record' },

  canRequestCancellation: { type: Boolean, default: false }
})

const emit = defineEmits(['request-cancellation', 'logs-updated'])

const waitIndicator = inject('waitIndicator')
const formatDate    = inject('formatDate')
const showMessage   = inject('showMessage')
const showError     = inject('showError')

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
})


const userId          = JSON.parse(localStorage.getItem('user')).id
const currentUserName = computed(() => JSON.parse(localStorage.getItem('user')).name)
const isProgrammer    = JSON.parse(localStorage.getItem('user')).permissions?.includes('is_programmer')

const modalEl             = ref(null)
const activeSourceId      = ref(null)   
const logs                = ref([])
const logsLoading         = ref(false)
const newMessage          = ref('')
const replyingTo          = ref(null)
const submitting          = ref(false)
const editingLog          = ref(null)
const editText            = ref('')
const cancellationRequest = ref(false)


const avatarPalette = [
  { bg: '#CECBF6', color: '#3C3489' },
  { bg: '#B5D4F4', color: '#0C447C' },
  { bg: '#9FE1CB', color: '#085041' },
  { bg: '#FAC775', color: '#633806' },
  { bg: '#F4C0D1', color: '#72243E' },
  { bg: '#C0DD97', color: '#3B6D11' },
]
const avatarBg    = (name) => avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].bg
const avatarColor = (name) => avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].color


const toggleReply = (key) => {
  replyingTo.value = replyingTo.value === key ? null : key
}


const getLogs = async () => {
  if (!activeSourceId.value) return
  logsLoading.value = true
  logs.value = []
  try {
    const response = await axiosInstance.get(`logs?source=${props.source}&source_id=${activeSourceId.value}`)
    logs.value = response.data
    emit('logs-updated', response.data.length)
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    logsLoading.value = false
  }
}


const submitLog = async (parent_id = null) => {
  if (!newMessage.value.trim()) return
  submitting.value = true
  try {
    await axiosInstance.post('logs', {
      parent_id,
      type: 'MESSAGE',
      reporter_id: userId,
      source: props.source,
      source_id: activeSourceId.value,
      module: props.module,
      description: newMessage.value.trim(),
      status_id: 1
    })
    newMessage.value = ''
    replyingTo.value = null
    getLogs()
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    submitting.value = false
  }
}


const updateLog = async (log) => {
  if (!editText.value.trim()) return
  submitting.value = true
  try {
    await axiosInstance.put(`logs/${log.id}`, { description: editText.value.trim() })
    showMessage('Note updated')
    cancelEdit()
    getLogs()
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    submitting.value = false
  }
}


const deleteRemark = async (logId) => {
  await axiosInstance.put(`logs/${logId}`, { deleted: 1 })
  showMessage('✔️')
  getLogs()
}


const startEdit  = (log) => { editingLog.value = log.id; editText.value = log.description }
const cancelEdit = ()    => { editingLog.value = null;   editText.value = '' }


const open = (parentModalId = null, sourceId = null) => {
  if (!sourceId) {
    console.warn('NoteModal.open() called without a sourceId — logs will not load.')
    return
  }

  activeSourceId.value = sourceId
  getLogs()

  const noteModal = Modal.getOrCreateInstance(modalEl.value)
  noteModal.show()

  if (parentModalId) {
    const parentEl = document.getElementById(parentModalId)
    modalEl.value.addEventListener('hidden.bs.modal', () => {
      document.body.classList.add('modal-open')
      if (parentEl) {
        parentEl.classList.add('show')
        parentEl.style.display = 'block'
      }
    }, { once: true })
  }
}

defineExpose({ open })
</script>

<style scoped>
.avatar-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 500;
}
.avatar-circle.avatar-sm { width: 28px; height: 28px; font-size: 11px; }
.avatar-circle.avatar-xs { width: 22px; height: 22px; font-size: 10px; }
</style>
